pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_polygon(n: i32) -> Polygon {
    let scale = f64::from(n);
    let mut polygon = Vec::with_capacity(2);

    let outer = vec![[0.0, 0.0], [scale, 0.0], [scale, scale], [0.0, scale]];
    polygon.push(outer);

    if n > 1 {
        let quarter = 0.25 * scale;
        let three_quarters = 0.75 * scale;
        let hole = vec![
            [quarter, quarter],
            [three_quarters, quarter],
            [three_quarters, three_quarters],
            [quarter, three_quarters],
        ];
        polygon.push(hole);
    }

    polygon
}

pub fn is_degenerate(ring: &Ring) -> bool {
    ring.len() < 3 || signed_area_twice(ring) == 0.0
}

fn signed_area_twice(ring: &Ring) -> f64 {
    let mut area = 0.0;

    for index in 0..ring.len() {
        let current = ring[index];
        let next = ring[(index + 1) % ring.len()];
        area += current[0] * next[1] - next[0] * current[1];
    }

    area
}

