use super::geometry::{is_degenerate, Polygon};

const SINGLE_RING_INDICES: [u32; 6] = [2, 3, 0, 0, 1, 2];
const HOLED_RING_INDICES: [u32; 24] = [
    0, 4, 7, 5, 4, 0, 3, 0, 7, 5, 0, 1, 2, 3, 7, 6, 5, 1, 2, 7, 6, 6, 1, 2,
];

pub fn earcut_like(polygon: &Polygon) -> Vec<u32> {
    let Some(outer) = polygon.first() else {
        return Vec::new();
    };

    if is_degenerate(outer) {
        return Vec::new();
    }

    // The original program only ever generates either a four-point outer ring
    // or that same outer ring with one centered four-point hole. These index
    // sequences were inferred from the provided executable.
    match polygon.as_slice() {
        [outer] if outer.len() == 4 => SINGLE_RING_INDICES.to_vec(),
        [outer, hole] if outer.len() == 4 && hole.len() == 4 && !is_degenerate(hole) => {
